// ✅ Get booked slots
export const getBookedSlots = async (
  doctorId,
  date
) => {
  const res = await API.get(
    "/appointments/booked-slots",
    {
      params: {
        doctorId,
        date,
      },
    }
  );

  return res.data;
};
